@startuml

class Employee {
  + Name : string
  + SocialSecurityNumber : string
  + IsOscarWinner : boolean
}

class CreativeEmployee extends Employee {
}

class Director extends CreativeEmployee {
  + AssistantName : string
}

class Actor extends CreativeEmployee {
  + Education : string
}

class Technician extends Employee {
  + FieldOfActivity : string
}

class FilmSet {
  + Location : string
}

class Film {
  + Title : string
  + YearOfRelease : int
}

enum Genre {
  Thriller
  Action
  Horror
  Comedy
}

class Screenwriter {
  + Name : string
  + MostSuccessfulFilm : string
}

class Screenplay {
  + Title : string
  + Version : string
  + Date : date
  + NumberOfScenes : int
  + Plot : string
}

class Novel {
  + Title : string
  + Author : string
}

class Concept {
}

class Role {
}

FilmSet "1..*" -- "1..*" Film : used for
Film "1" -- "1" Genre
Film "1" -- "1" Screenplay : based on
Screenplay "1" -- "1" Screenwriter : written by
Screenplay "0..*" -- "0..1" Novel : based on
Screenplay "0..*" -- "0..1" Concept : based on
Actor "1..*" -- "1" Role : plays
Role "1" -- "1" Screenplay : involves
Screenplay "1" -- "1" Film : written for

@enduml

